34	// Select the cycle-accurate engine for `run --model accurate` from an
35	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
36	// to the sole cycle-accurate engine -- erroring if there are none or more than
37	// one (ambiguous). With `want_id` set, that engine must exist and be
38	// cycle-accurate. Returns nullptr and sets `err` (naming the available
39	// cycle-accurate ids) on any failure; the returned pointer aliases into
40	// `engines`, so it must outlive the result.
41	inline const EngineDescriptor* resolve_accurate_engine(
42	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
43	    std::string& err) {
44	  auto is_accurate = [](const EngineDescriptor& e) {
45	    return e.kind == "cycle-accurate";
46	  };
47	  auto accurate_ids = [&] {
48	    std::string s;
49	    for (const EngineDescriptor& e : engines)
50	      if (is_accurate(e)) s += (s.empty() ? "" : ", ") + e.id;
51	    return s;
52	  };
53	
54	  if (!want_id.empty()) {  // explicit --engine
55	    for (const EngineDescriptor& e : engines) {
56	      if (e.id != want_id) continue;
57	      if (is_accurate(e)) return &e;
58	      err = "engine '" + want_id + "' is " +
59	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
60	            "; model accurate needs a cycle-accurate engine";
61	      return nullptr;
62	    }
63	    std::string have = accurate_ids();
64	    err = "no engine '" + want_id + "'" +
65	          (have.empty() ? " (no cycle-accurate engines found)"
66	                        : " (cycle-accurate engines: " + have + ")");
67	    return nullptr;
68	  }
69	
70	  // No --engine: default to the sole cycle-accurate engine.
71	  const EngineDescriptor* sole = nullptr;
72	  int n = 0;
73	  for (const EngineDescriptor& e : engines)
74	    if (is_accurate(e)) { sole = &e; ++n; }
75	  if (n == 1) return sole;
76	  if (n == 0)
77	    err = "model accurate: no cycle-accurate engine found "
78	          "(build one with: andes-sim build --what vsim)";
79	  else
80	    err = "model accurate: multiple cycle-accurate engines; select one with "
81	          "--engine (have: " + accurate_ids() + ")";
82	  return nullptr;
83	}
